// An integer group: the subgroup of order q = 11 in Z_23^*, generated by g = 4.
// The group operation is multiplication modulo p; the identity is 1.
// Real DH uses p with 2048 bits or more; these small numbers fit on a slide.

pub const P: u64 = 23; // Modulus.
pub const Q: u64 = 11; // Order of g: g^11 = 1 (mod 23).
pub const G: u64 = 4; // Generator.

// The group operation: a * b mod p.
pub fn op(a: u64, b: u64) -> u64 {
    a * b % P
}

// "g^x" means: apply the group operation x times, starting from the identity 1.
// Every step reduces modulo p, so this is not the integer power 4^x.
pub fn repeat(g: u64, x: u64) -> u64 {
    let mut result = 1; // Identity.
    for _ in 0..x {
        result = op(result, g);
    }
    result
}

// The order of a: the smallest x >= 1 with a^x = 1.
// It divides p - 1 = 22 (the number of elements of Z_23^*), so it is never the modulus p.
pub fn order(a: u64) -> u64 {
    let mut x = 1;
    while repeat(a, x) != 1 {
        x += 1;
    }
    x
}

#[cfg(test)]
mod tests {
    use super::{order, repeat, G, P, Q};

    #[test]
    fn orders_divide_p_minus_1() {
        assert_eq!(order(G), Q);
        assert_eq!(order(1), 1);
        assert_eq!(order(P - 1), 2); // 22 = -1 mod 23.
        assert_eq!(order(5), P - 1); // 5 generates all of Z_23^*.
        for a in 1..P {
            assert_eq!((P - 1) % order(a), 0);
        }
    }

    #[test]
    fn g_has_order_q() {
        assert_eq!(repeat(G, Q), 1);
        for x in 1..Q {
            assert_ne!(repeat(G, x), 1); // No smaller x gives the identity.
        }
    }

    #[test]
    fn group_power_is_integer_power_mod_p() {
        for x in 0..20 {
            assert_eq!(repeat(G, x), G.pow(x as u32) % P);
        }
    }

    #[test]
    fn exponents_work_modulo_q() {
        for x in 0..50 {
            assert_eq!(repeat(G, x), repeat(G, x % Q));
        }
    }
}
